function Panel({ children, style, className }) {
  return (
    <div className={"panel" + (className ? " " + className : "")} style={style}>
      <span className="corner-tr" /><span className="corner-bl" />
      {children}
    </div>
  );
}

function AtlasIcon() {
  return (
    <svg width="38" height="54" viewBox="0 0 60 84" fill="none" style={{flexShrink:0}}>
      <polygon points="30,2 58,30 30,42 2,30"  fill="#c8d8e0" stroke="#00e5ff" strokeWidth="0.8" opacity="0.9"/>
      <polygon points="2,30 30,2 30,42"         fill="#7a9aaa" stroke="#00e5ff" strokeWidth="0.5"/>
      <polygon points="2,30 30,42 30,82"         fill="#1a2530" stroke="#00e5ff" strokeWidth="0.8"/>
      <polygon points="58,30 30,82 30,42"        fill="#0d1820" stroke="#00e5ff" strokeWidth="0.8"/>
      <ellipse cx="36" cy="38" rx="10" ry="10"  fill="#cc2233" opacity="0.85"/>
      <line x1="30" y1="2"  x2="30" y2="42" stroke="#00e5ff" strokeWidth="0.6" opacity="0.5"/>
      <line x1="2"  y1="30" x2="58" y2="30" stroke="#00e5ff" strokeWidth="0.6" opacity="0.4"/>
      <polygon points="30,2 58,30 30,42 2,30" fill="none" stroke="#00e5ff" strokeWidth="1" opacity="0.6"/>
    </svg>
  );
}

function HazBar({ label, value, color, gradTo }) {
  var bg = gradTo ? "linear-gradient(90deg," + color + "," + gradTo + ")" : color;
  return (
    <div style={{marginBottom:8}}>
      <div style={{display:"flex",justifyContent:"space-between",fontSize:11,marginBottom:4}}>
        <span style={{color:"#6699aa",letterSpacing:1}}>{label}</span>
        <span style={{color:color,fontFamily:"'Orbitron',sans-serif",fontSize:10}}>{value}%</span>
      </div>
      <div style={{height:5,background:"rgba(255,255,255,0.06)",borderRadius:3}}>
        <div className="haz-fill" style={{height:"100%",width:value+"%",background:bg,borderRadius:3,boxShadow:"0 0 8px " + color}}/>
      </div>
    </div>
  );
}

function Cell({ label, value, accent, col }) {
  var o = accent === "o";
  var vc = col || (o?"#ff6d00":"#00e5ff");
  return (
    <div style={{background:o?"rgba(255,109,0,0.05)":"rgba(0,229,255,0.04)",border:o?"1px solid rgba(255,109,0,0.18)":"1px solid rgba(0,229,255,0.13)",padding:12}}>
      <div style={{fontSize:10,color:o?"#996644":"#446688",marginBottom:5,letterSpacing:1}}>{label}</div>
      <div style={{fontSize:13,color:vc,fontFamily:"'Orbitron',sans-serif"}}>{value}</div>
    </div>
  );
}

function StatCard({ label, value, icon, valueColor, extra }) {
  return (
    <div className="stat-card">
      <div style={{fontSize:9,color:"#335566",marginBottom:5,letterSpacing:2,display:"flex",alignItems:"center",gap:6}}>
        {icon && <span style={{fontSize:11,opacity:0.7}}>{icon}</span>}{label}
      </div>
      <div style={{display:"flex",alignItems:"center",gap:6}}>
        <div style={{fontSize:15,color:valueColor||"#00e5ff",fontFamily:"'Orbitron',sans-serif"}}>{value}</div>
        {extra}
      </div>
    </div>
  );
}

function Modal({ onClose, cvt, u, planet }) {
  var p = planet || PLANET_DATA;
  var sc = p.sentinels==="Passive"?"#00ff88":p.sentinels==="Hostile"?"#ffab00":"#ff5555";
  return (
    <div className="modal-bg" onClick={onClose}>
      <div className="modal scan-in" onClick={function(e){ e.stopPropagation(); }}>
        <span className="corner-tr" style={{position:"absolute",top:-1,right:-1}}/>
        <span className="corner-bl" style={{position:"absolute",bottom:-1,left:-1}}/>
        <div style={{position:"relative",height:230,overflow:"hidden"}}>
          <img src={BIOME_IMG[p.type]||BIOME_IMG["Dead"]} style={{position:"absolute",top:0,left:0,width:"100%",height:"100%",objectFit:"cover",objectPosition:"center",filter:p.type==="Radioactive"?"hue-rotate(90deg) saturate(2.5) brightness(0.6) contrast(1.1)":"none"}}/>
          <PlanetOrb type={p.type} size={130}/>
          <div style={{position:"absolute",top:0,left:0,right:0,bottom:0,zIndex:2,background:"linear-gradient(to bottom,rgba(0,0,0,0.25) 30%,#050f1c)"}}/>
          <div style={{position:"absolute",inset:0,zIndex:3,pointerEvents:"none",overflow:"hidden"}}>
            <BiomeParticles type={p.type}/>
          </div>
          <div style={{position:"absolute",top:14,left:14,fontSize:10,color:"#ff6d00",background:"rgba(0,0,0,0.78)",padding:"3px 10px",border:"1px solid rgba(255,109,0,0.42)",letterSpacing:2,zIndex:4}}>
            ◈ PLANET SCAN ACTIVE
          </div>
          <div style={{position:"absolute",bottom:20,left:20,zIndex:4}}>
            <div style={{fontFamily:"'Orbitron',sans-serif",fontSize:24,fontWeight:900,color:"#00e5ff",textShadow:"0 0 24px rgba(0,229,255,0.9)"}}>{p.name}</div>
            <div style={{fontSize:11,color:"#88ff44",marginTop:4,letterSpacing:2}}>{p.type.toUpperCase()} WORLD</div>
          </div>
        </div>
        <div style={{padding:"20px 20px 24px"}}>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:14,marginBottom:14}}>
            <Cell label="STAR SYSTEM"  value={p.system} accent="c"/>
            <Cell label="PLANET INDEX" value={p.planetNumber + " of " + p.systemPlanetCount} accent="c"/>
            <Cell label="SURFACE TEMP" value={cvt(p.temperature) + u} accent="o"/>
            <Cell label="WEATHER"      value={p.weather} accent="o"/>
          </div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:14,marginBottom:22}}>
            <Cell label="MOONS" value={(p.moons||0) + (p.moons===1?" Satellite":" Satellites")} accent="c"/>
            <Cell label="CLASSIFICATION" value={p.planetClass||"Rocky"} accent="c"/>
            <Cell label="STAR TYPE" value={p.systemType||"Unknown"} col={{"Yellow Star":"#ffcc44","Red Dwarf":"#ff5555","Blue Star":"#66aaff","Green Star":"#44ff88","Binary Star":"#ff9944","Exotic":"#cc66ff"}[p.systemType]||"#aabbcc"}/>
          </div>
          <div style={{marginBottom:20}}>
            <div className="section-label">◈ HAZARD ANALYSIS</div>
            <HazBar label="TOXICITY"  value={p.hazards.toxicity}  color="#00ff88" gradTo="#44ffaa"/>
            <HazBar label="RADIATION" value={p.hazards.radiation} color="#ccff00" gradTo="#ffff44"/>
            <HazBar label="COLD"      value={p.hazards.cold}      color="#44aaff" gradTo="#88ddff"/>
            <HazBar label="HEAT"      value={p.hazards.heat}      color="#ff6d00" gradTo="#ffaa44"/>
          </div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:14,marginBottom:18}}>
            <div style={{background:"rgba(0,229,255,0.03)",border:"1px solid rgba(0,229,255,0.1)",padding:12}}>
              <div style={{fontSize:10,color:"#446688",marginBottom:6,letterSpacing:1}}>SENTINEL ACTIVITY</div>
              <div style={{fontSize:12,color:sc,fontFamily:"'Orbitron',sans-serif"}}>◉ {p.sentinels.toUpperCase()}</div>
            </div>
            <div style={{background:"rgba(0,229,255,0.03)",border:"1px solid rgba(0,229,255,0.1)",padding:12}}>
              <div style={{fontSize:10,color:"#446688",marginBottom:6,letterSpacing:1}}>RESOURCES</div>
              <div style={{fontSize:11,color:"#88ccdd",lineHeight:1.8}}>{p.resources.map(function(r,i){ return <div key={i}>· {r}</div>; })}</div>
            </div>
          </div>
          <div style={{background:"rgba(0,229,255,0.02)",border:"1px solid rgba(0,229,255,0.09)",padding:14,marginBottom:18}}>
            <div style={{fontSize:10,color:"#446688",marginBottom:6,letterSpacing:1}}>ATMOSPHERIC COMPOSITION</div>
            <div style={{fontSize:12,color:"#7799aa",lineHeight:1.7}}>{p.atmosphere}</div>
          </div>
          <button className="btn-r" onClick={onClose} style={{width:"100%",padding:"11px",fontSize:12,letterSpacing:3}}>CLOSE SCAN</button>
        </div>
      </div>
    </div>
  );
}

function PlanetOrb({ type, size }) {
  var s = size || 100;
  var orb = BIOME_ORB[type] || BIOME_ORB["Dead"];
  var img = PLANET_ORB_IMG[type] || PLANET_ORB_IMG["Dead"];
  var glowFar = orb.glow.replace(/[\d.]+\)$/, "0.22)");
  return (
    <div style={{
      position:"absolute", left:"50%", top:"45%",
      transform:"translate(-50%,-50%)",
      width:s+"px", height:s+"px", borderRadius:"50%",
      overflow:"hidden",
      boxShadow:"0 0 40px "+orb.glow+",0 0 90px "+glowFar+",0 0 0 1px "+orb.rim,
      zIndex:1, pointerEvents:"none"
    }}>
      {img
        ? <img src={img} className="orb-spin" style={{width:"110%",height:"110%",objectFit:"contain",display:"block",marginTop:"-5%",marginLeft:"-5%",filter:type==="Radioactive"?"hue-rotate(90deg) saturate(4) brightness(0.72) contrast(1.1)":"none"}}/>
        : <div style={{width:"100%",height:"100%",background:orb.grad}}/>
      }
    </div>
  );
}

function WeatherParticles({ code, windDir }) {
  var isSnow    = (code >= 71 && code <= 77) || code === 85 || code === 86;
  var isRain    = (!isSnow) && ((code >= 51 && code <= 82) || code >= 95);
  var isHeavy   = code === 65 || code === 82 || code >= 95;
  var isThunder = code >= 95;
  var isFog     = code === 45 || code === 48;
  if (!isSnow && !isRain && !isFog) return null;
  var wdRad    = ((windDir || 0) * Math.PI) / 180;
  var windTilt = Math.round(8 + Math.sin(wdRad) * 10);
  var rainCount = isHeavy ? 80 : 22;
  // Depth layers: [sizeMult, opacityMult, speedMult]
  var L = [[0.62,0.45,1.55],[1.0,0.78,1.0],[1.42,1.0,0.68]];
  var pts = [];
  if (isSnow) {
    for (var i = 0; i < 40; i++) {
      var lyr = L[i % 3];
      var left  = (i * 2.63 + i * i * 0.17) % 100;
      var delay = (i * 0.14) % 3.2;
      var sz    = Math.max(1, Math.round(lyr[0] * (2 + (i % 3))));
      var dur   = ((3.2 + (i * 0.18) % 2.6) / lyr[2]).toFixed(1);
      var sx    = (8 + (i % 5) * 5) * (i % 2 === 0 ? 1 : -1);
      pts.push(<div key={i} style={{
        position:"absolute", left:left+"%", top:"-24px",
        width:sz+"px", height:sz+"px", borderRadius:"50%",
        background:"rgba(218,240,255,"+(Math.round(lyr[1]*88)/100)+")",
        boxShadow:"0 0 "+(sz+2)+"px rgba(195,232,255,0.65)",
        animation:"snowDrift "+dur+"s ease-in-out "+delay.toFixed(2)+"s infinite",
        "--sx":sx+"px", opacity:lyr[1], pointerEvents:"none"
      }}/>);
    }
  } else if (isFog) {
    for (var i = 0; i < 14; i++) {
      var lyr = L[i % 3];
      var bw  = 160 + (i * 43) % 250;
      var bh  = Math.round(bw * (0.28 + (i % 4) * 0.08));
      var left = (i * 7.7 + 3) % 92;
      var top  = 5 + (i * 7.3) % 82;
      var delay = ((i * 0.65) % 5.5).toFixed(1);
      var dur  = ((9 + (i * 1.4) % 8) / lyr[2]).toFixed(1);
      var op   = ((0.10 + (i % 4) * 0.04) * lyr[1]).toFixed(2);
      pts.push(<div key={i} style={{
        position:"absolute", left:left+"%", top:top+"%",
        width:bw+"px", height:bh+"px", borderRadius:"50%",
        background:"radial-gradient(ellipse,rgba(155,195,220,"+op+") 0%,rgba(100,155,190,"+(op*0.4).toFixed(2)+") 45%,transparent 70%)",
        animation:"fogDrift "+dur+"s ease-in-out "+delay+"s infinite alternate",
        transform:"scale("+lyr[0]+")", transformOrigin:"center", pointerEvents:"none"
      }}/>);
    }
  } else {
    for (var i = 0; i < rainCount; i++) {
      var lyr = L[i % 3];
      var left  = (i * 1.29 + i * i * 0.07) % 100;
      var delay = ((i * 0.035) % 1.5).toFixed(2);
      var ht    = Math.round(lyr[0] * (isHeavy ? 14+(i%6)*2 : 8+(i%5)));
      var wid   = (Math.round(lyr[0] * (isHeavy ? 2.0 : 1.5) * 10) / 10).toFixed(1);
      var rdur  = ((isHeavy ? 0.28+(i*0.007)%0.14 : 0.52+(i*0.016)%0.32) / lyr[2]).toFixed(2);
      var op    = ((isHeavy ? 0.60 : 0.42) * lyr[1]).toFixed(2);
      var angle = windTilt + (i % 3 - 1) * 2;
      pts.push(<div key={i} style={{
        position:"absolute", left:left+"%", top:"-32px",
        width:wid+"px", height:ht+"px",
        background:"linear-gradient(transparent,rgba(125,195,255,"+op+"))",
        animation:"rainFall "+rdur+"s linear "+delay+"s infinite",
        "--ra":angle+"deg", pointerEvents:"none"
      }}/>);
    }
    if (isHeavy) pts.push(<div key="sheet" style={{position:"absolute",inset:0,background:"linear-gradient(to bottom,transparent,rgba(80,135,200,0.04) 45%,rgba(80,135,200,0.07))",pointerEvents:"none"}}/>);
  }
  return (
    <div style={{position:"absolute",inset:0,overflow:"hidden",pointerEvents:"none",
      WebkitMaskImage:"linear-gradient(to bottom,black 60%,transparent 100%)",
      maskImage:"linear-gradient(to bottom,black 60%,transparent 100%)"}}>
      {pts}
      {isThunder && <div style={{position:"absolute",inset:0,background:"rgba(200,220,255,0.75)",animation:"lightning 7s ease-in-out 1.5s infinite",pointerEvents:"none"}}/>}
    </div>
  );
}

function SnowOverlay() {
  var flakes = [];
  for (var i = 0; i < 18; i++) {
    var left  = (i * 5.8 + i * i * 0.35) % 100;
    var sz    = 2 + (i % 3);
    var dur   = 2.4 + (i * 0.22) % 2.2;
    var delay = (i * 0.17) % 1.8;
    flakes.push(
      <div key={i} style={{
        position:"absolute", left:left+"%", top:"-10px",
        width:sz+"px", height:sz+"px", borderRadius:"50%",
        background:"rgba(222,242,255,0.92)",
        boxShadow:"0 0 4px rgba(195,232,255,0.8)",
        animation:"snowFall "+dur+"s linear "+delay+"s infinite",
        pointerEvents:"none"
      }}/>
    );
  }
  return <div style={{position:"absolute",inset:0,overflow:"hidden",pointerEvents:"none",zIndex:1}}>{flakes}</div>;
}

const PLANET_ORB_IMG = {
  "Frozen": "data:image/png;base64,",
  "Lush": "data:image/png;base64,",
  "Dead": "data:image/png;base64,",
  "Toxic": "data:image/png;base64,",
  "Volcanic": "data:image/png;base64,",
  "Scorched": "data:image/png;base64,",
  "Marsh": "data:image/png;base64,",
  "Radioactive": "data:image/png;base64,",
  "Barren": "data:image/png;base64,",
};

var BIOME_PARTICLES = {
  "Frozen":     { type:"snow",  count:22, color:"rgba(200,235,255,0.88)", glow:"rgba(195,232,255,0.7)" },
  "Toxic":      { type:"rain",  count:30, color:"rgba(120,255,40,0.72)",  glow:null },
  "Lush":       { type:"rain",  count:18, color:"rgba(130,190,255,0.55)", glow:null },
  "Scorched":   { type:"ash",   count:18, color:"rgba(255,130,20,0.75)",  glow:"rgba(255,80,0,0.5)"  },
  "Radioactive":{ type:"fog",   count:7,  color:"rgba(170,255,40,0.16)",  glow:null },
  "Dead":       { type:"fog",   count:6,  color:"rgba(70,70,60,0.11)",    glow:null },
  "Marsh":      { type:"fog",   count:7,  color:"rgba(50,130,90,0.14)",   glow:null },
  "Volcanic":   { type:"ash",   count:22, color:"rgba(255,50,0,0.82)",    glow:"rgba(255,30,0,0.55)" },
};

function BiomeParticles({ type }) {
  var c = BIOME_PARTICLES[type] || BIOME_PARTICLES["Dead"];
  var pts = [];
  var isEmber = c.type === "ash" && (type === "Volcanic" || type === "Scorched");
  var containerStyle = {position:"absolute",inset:0,overflow:"hidden",pointerEvents:"none"};
  if (type === "Toxic") containerStyle.boxShadow = "inset 0 0 70px rgba(60,210,10,0.13)";
  // Frozen: large background depth flakes
  if (type === "Frozen") {
    for (var j = 0; j < 6; j++) {
      var bleft = (j * 16.3 + 5) % 88;
      var bsz   = 10 + (j % 3) * 3;
      var bsx   = (j % 2 === 0 ? 7 : -7);
      pts.push(<div key={"bg"+j} style={{
        position:"absolute", left:bleft+"%", top:"-20px",
        width:bsz+"px", height:bsz+"px", borderRadius:"50%",
        background:"rgba(200,230,255,0.12)", boxShadow:"0 0 10px rgba(185,220,255,0.18)",
        animation:"snowDrift "+(5+j*0.9)+"s ease-in-out "+(j*0.8)+"s infinite",
        "--sx":bsx+"px", pointerEvents:"none"
      }}/>);
    }
  }
  for (var i = 0; i < c.count; i++) {
    var left  = (i * 3.71 + i * i * 0.19) % 100;
    var delay = (i * 0.13) % 2.2;
    var sz    = 2 + (i % 3);
    var dur   = 2.2 + (i * 0.09) % 2.0;
    if (c.type === "snow") {
      var sx = (6 + (i%4)*3) * (i%2===0?1:-1);
      pts.push(<div key={i} style={{
        position:"absolute", left:left+"%", top:"-10px",
        width:sz+"px", height:sz+"px", borderRadius:"50%",
        background:c.color, boxShadow:c.glow ? "0 0 4px "+c.glow : "none",
        animation:"snowDrift "+dur+"s ease-in-out "+delay+"s infinite", "--sx":sx+"px"
      }}/>);
    } else if (c.type === "rain") {
      var h = 8 + (i % 8);
      pts.push(<div key={i} style={{
        position:"absolute", left:left+"%", top:"-14px",
        width:"1.5px", height:h+"px", background:c.color,
        animation:"rainFall "+(0.7+(i*0.04)%0.8)+"s linear "+delay+"s infinite", "--ra":"10deg"
      }}/>);
    } else if (c.type === "ash") {
      var eSz  = 2 + (i % 5);
      var goUp = isEmber && (i % 3 === 0);
      pts.push(<div key={i} style={{
        position:"absolute", left:left+"%",
        top:goUp?"auto":"-10px", bottom:goUp?"-10px":"auto",
        width:eSz+"px", height:eSz+"px", borderRadius:"30%",
        background:c.color,
        boxShadow:c.glow ? "0 0 "+(eSz+2)+"px "+c.glow : "none",
        filter:isEmber && i%3===1 ? "blur(0.5px)" : "none",
        animation:(goUp?"emberRise":"snowFall")+" "+(dur+(goUp?1.2:0.8))+"s linear "+delay+"s infinite"
      }}/>);
    } else if (c.type === "fog") {
      var fw = 80 + (i * 23) % 120;
      var fh = Math.round(fw * (0.32 + (i%3)*0.08));
      pts.push(<div key={i} style={{
        position:"absolute", left:(i*13)%88+"%", top:(12+(i*11)%68)+"%",
        width:fw+"px", height:fh+"px", borderRadius:"50%",
        background:"radial-gradient(ellipse,"+c.color+" 0%,transparent 70%)",
        animation:"fogDrift "+(4+(i*0.5)%4)+"s ease-in-out "+delay+"s infinite alternate"
      }}/>);
    }
  }
  return <div style={containerStyle}>{pts}</div>;
}

function App() {
  const [weather,      setWeather]      = useState(MOCK_WEATHER);
  const [scanner,      setScanner]      = useState(false);
  const [modal,        setModal]        = useState(false);
  const [celsius,      setCelsius]      = useState(true);
  const [time,         setTime]         = useState(new Date());
  const [locInput,     setLocInput]     = useState("");
  const [loading,      setLoading]      = useState(false);
  const [locErr,       setLocErr]       = useState("");
  const [planIdx,      setPlanIdx]      = useState(0);
  const [planFade,     setPlanFade]     = useState(false);
  var planet = PLANETS[planIdx];
  function cyclePlanet(dir) {
    setPlanFade(true);
    setTimeout(function() {
      setPlanIdx(function(p) { return (p + dir + PLANETS.length) % PLANETS.length; });
      setPlanFade(false);
    }, 150);
  }
  const [sisterPopup,  setSisterPopup]  = useState(false);

  const w   = weather;
  const cvt = v => celsius ? v : Math.round(v * 9/5 + 32);
  const u   = celsius ? "°C" : "°F";

  useEffect(() => {
    const t = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(t);
  }, []);

  const doSearch = (q) => {
    setLoading(true); setLocErr("");
    forwardGeocode(q)
      .then(geo => {
        if (!geo) { setLocErr("LOCATION NOT FOUND"); setLoading(false); return; }
        fetchWeatherData(geo.lat, geo.lon, geo.city)
          .then(wx => { setWeather(wx); setLocInput(""); setLoading(false); })
          .catch(() => { setLocErr("SIGNAL LOST"); setLoading(false); });
      })
      .catch(() => { setLocErr("SIGNAL LOST"); setLoading(false); });
  };

  const tryIPLocate = () => {
    setLoading(true); setLocErr("");
    fetch("https://ipapi.co/json/")
      .then(function(r){ return r.json(); })
      .then(function(d){
        if (d.latitude && d.longitude) {
          return fetchWeatherData(d.latitude, d.longitude, d.city || d.region || "Unknown")
            .then(function(wx){ setWeather(wx); setLoading(false); });
        }
        setLocErr("SIGNAL LOST — TYPE LOCATION MANUALLY"); setLoading(false);
      })
      .catch(function(){ setLocErr("SIGNAL LOST — TYPE LOCATION MANUALLY"); setLoading(false); });
  };

  const handleLocate = () => {
    if (!navigator.geolocation) { tryIPLocate(); return; }
    setLoading(true); setLocErr("");
    navigator.geolocation.getCurrentPosition(
      function(pos) {
        var lat = pos.coords.latitude;
        var lon = pos.coords.longitude;
        reverseGeocode(lat, lon)
          .then(function(city){ return fetchWeatherData(lat, lon, city); })
          .then(function(wx){ setWeather(wx); setLoading(false); })
          .catch(function(){ setLocErr("SIGNAL LOST"); setLoading(false); });
      },
      function() { tryIPLocate(); }
    );
  };

  var ts = time.toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"});
  var ds = time.toLocaleDateString([], {weekday:"long",year:"numeric",month:"long",day:"numeric"});
  var tz = Intl.DateTimeFormat().resolvedOptions().timeZone || "LOCAL";

  var _h    = time.getHours();
  var _srH  = parseInt((w.sunrise||"06:00").split(":")[0]);
  var _ssH  = parseInt((w.sunset||"20:00").split(":")[0]);
  var _isG  = (_h===_srH||_h===_srH+1||_h===_ssH-1||_h===_ssH);
  var _isN  = (_h < _srH || _h > _ssH+1);
  var _bg   = _isN ? "rgba(2,5,20,0.97)" : _isG ? "rgba(12,9,3,0.96)" : "rgba(0,14,26,0.94)";
  var _glow = _isN ? "0 0 40px rgba(30,50,130,0.22)" : _isG ? "0 0 40px rgba(190,90,15,0.16)" : "0 0 40px rgba(0,229,255,0.04)";

  return (
    <div>
      <style>{css}</style>
      <div className="grid-bg"/>
      <div className="scanlines"/>
      <div className="app">

        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:18,paddingBottom:14}}>
          <div style={{display:"flex",alignItems:"flex-start",gap:14}}>
            <AtlasIcon/>
            <div>
              <div className="glow" style={{fontFamily:"'Orbitron',sans-serif",fontSize:18,fontWeight:900,color:"#00e5ff",lineHeight:1}}>ATLAS WEATHER SYSTEM</div>
              <div style={{fontSize:10,color:"#2a4a5a",marginTop:5,letterSpacing:1.5}}>NO MAN'S SKY — ENVIRONMENTAL MONITORING</div>
              <div style={{fontSize:9,color:"#192d38",marginTop:2,letterSpacing:1}}>{tz.toUpperCase()}</div>
            </div>
          </div>
          <div style={{textAlign:"right"}}>
            <div className="glow" style={{fontSize:22,fontFamily:"'Orbitron',sans-serif",color:"#00e5ff"}}>{ts}</div>
            <div style={{fontSize:10,color:"#2a4a5a",marginTop:5}}>{ds}</div>
          </div>
        </div>

        <div className="loc-bar">
          <input className="loc-input" value={locInput} placeholder="ENTER CITY OR LOCATION NAME..."
            onChange={function(e){ setLocInput(e.target.value); }}
            onKeyDown={function(e){ if (e.key === "Enter" && locInput.trim()) doSearch(locInput.trim()); }}
            disabled={loading}/>
          <button className="loc-btn" onClick={function(){ if (locInput.trim()) doSearch(locInput.trim()); }} disabled={loading || !locInput.trim()}>SCAN</button>
          <button className="loc-btn" onClick={handleLocate} disabled={loading}>LOCATE</button>
        </div>
        {loading && <div className="acq" style={{textAlign:"center",marginBottom:10}}>ACQUIRING SIGNAL...</div>}
        {locErr  && <div className="loc-err">{locErr}</div>}

        <Panel style={{padding:24,marginBottom:14,background:_bg,boxShadow:_glow}}>
          <div className="weather-top" style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",flexWrap:"wrap",gap:16}}>
            <div style={{display:"flex",alignItems:"flex-start",gap:18}}>
              <img src={SENTINEL_IMG} alt="Sentinel"
                   style={{width:84,height:84,objectFit:"contain",mixBlendMode:"screen",
                           filter:"drop-shadow(0 0 12px rgba(0,229,255,0.6)) brightness(1.05)"}}/>
              <div>
                <div style={{fontSize:10,color:"#2a4a5a",letterSpacing:3,marginBottom:6}}>LOCATION: {w.city.toUpperCase()}</div>
                <div className="glow temp-breathe" style={{fontFamily:"'Orbitron',sans-serif",fontSize:60,fontWeight:900,color:"#00e5ff",lineHeight:1}}>
                  {cvt(w.temp)}{u}
                </div>
                <div style={{fontSize:14,color:"#6699aa",marginTop:10}}>{w.condition}</div>
                <div style={{fontSize:11,color:"#2a4a5a",marginTop:3}}>Feels like {cvt(w.feels)}{u}</div>
              </div>
            </div>
            <div className="weather-btns" style={{display:"flex",flexDirection:"column",gap:8}}>
              <button className="btn-o" onClick={function(){ setCelsius(!celsius); }}>
                <span className="sw"/>Switch to {celsius?"°F":"°C"}
              </button>
              <button className="btn-o" onClick={function(){
                  setScanner(!scanner);
                }}>
                <span className="sw"/>NMS PLANET SCANNER
              </button>
            </div>
          </div>
          <div style={{position:"absolute",inset:0,overflow:"hidden",pointerEvents:"none",zIndex:5}}>
            <WeatherParticles code={w.weatherCode || 0} windDir={w.windDir || 0}/>
          </div>
        </Panel>

        <div className="stat-grid" style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:8,marginBottom:8}}>
          <StatCard label="HUMIDITY"   value={w.humidity + "%"}    icon="~"/>
          <StatCard label="WIND SPEED" value={w.wind+" km/h"} icon="~" extra={<svg width="14" height="14" viewBox="0 0 14 14" style={{flexShrink:0,opacity:0.75}}><g transform={"rotate("+(w.windDir||0)+",7,7)"}><polygon points="7,1 10,11 7,9 4,11" fill="#00e5ff"/></g></svg>}/>
          <StatCard label="UV INDEX" value={w.uv} icon="O" valueColor={w.uv<=2?"#00ff88":w.uv<=5?"#eedd44":w.uv<=7?"#ff9944":w.uv<=10?"#ff5544":"#cc44ff"}/>
          <StatCard label="VISIBILITY" value={w.visibility + " km"} icon="o"/>
          <StatCard label="PRESSURE"   value={w.pressure + " hPa"} icon="O"/>
          <StatCard label="PRECIP."    value={w.precip + " mm"}    icon="|"/>
        </div>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:14}}>
          <StatCard label="SUNRISE" value={w.sunrise} icon="^"/>
          <StatCard label="SUNSET"  value={w.sunset}  icon="v"/>
        </div>

        <Panel style={{padding:18,marginBottom:14}}>
          <div className="section-label">NEXT 12 HOURS</div>
          <div className="hourly-strip">
            {w.hourly.map(function(h,i) {
              return (
                <div key={i} className={"h-cell" + (i===0 ? " now" : "")}>
                  <div style={{fontSize:9,color:i===0?"#00e5ff":"#2a4a5a",marginBottom:4,letterSpacing:1}}>{h.hour}</div>
                  <div style={{fontSize:18,margin:"4px 0"}}>{h.icon}</div>
                  <div style={{fontSize:11,color:"#00e5ff",fontFamily:"'Orbitron',sans-serif"}}>{cvt(h.temp)}{u}</div>
                </div>
              );
            })}
          </div>
        </Panel>

        <Panel style={{padding:18,marginBottom:14}}>
          <div className="section-label">7-DAY FORECAST</div>
          <div className="fc-grid" style={{display:"grid",gridTemplateColumns:"repeat(7,1fr)",gap:6}}>
            {w.forecast.map(function(d,i) {
              return (
                <div key={i} className="fc-day">
                  <div style={{fontSize:10,color:"#2a4a5a",marginBottom:4}}>{d.day}</div>
                  <div style={{fontSize:22,margin:"4px 0"}}>{d.icon}</div>
                  <div style={{fontSize:11,color:"#00e5ff",fontFamily:"'Orbitron',sans-serif"}}>{cvt(d.high)}{u}</div>
                  <div style={{fontSize:10,color:"#335566",marginTop:2}}>{cvt(d.low)}</div>
                </div>
              );
            })}
          </div>
        </Panel>

        {scanner && (
          <Panel className="scan-in" style={{padding:20}}>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16}}>
              <div>
                <div className="glow-o" style={{fontFamily:"'Orbitron',sans-serif",fontSize:14}}>PLANETARY SCANNER</div>
                <div style={{fontSize:9,color:"#2a4a5a",marginTop:3,letterSpacing:2}}>WORLD {planIdx+1} OF {PLANETS.length}</div>
              </div>
              <div style={{display:"flex",gap:8,alignItems:"center"}}>
                <button className="loc-btn" onClick={function(){ cyclePlanet(-1); }} style={{padding:"4px 12px",fontSize:14}}>&#9664;</button>
                <button className="loc-btn" onClick={function(){ cyclePlanet(1); }} style={{padding:"4px 12px",fontSize:14}}>&#9654;</button>
                <button className="btn-r" onClick={function(){ setScanner(false); }} style={{padding:"4px 14px",fontSize:11,letterSpacing:1}}>X CLOSE</button>
              </div>
            </div>
            <div className="planet-card" onClick={function(){ setModal(true); }} style={{opacity:planFade?0:1,transition:"opacity 0.15s ease"}}>
              <span className="csl"/>
              <div style={{position:"relative",height:160,overflow:"hidden"}}>
                <img src={BIOME_IMG[planet.type]||BIOME_IMG["Dead"]} style={{position:"absolute",top:0,left:0,width:"100%",height:"100%",objectFit:"cover",objectPosition:"center",filter:planet.type==="Radioactive"?"hue-rotate(90deg) saturate(2.5) brightness(0.6) contrast(1.1)":"none"}}/>
                <PlanetOrb type={planet.type} size={88}/>
                <div style={{position:"absolute",top:0,left:0,right:0,bottom:0,zIndex:2,background:"linear-gradient(to bottom,transparent 45%,rgba(0,5,12,0.98))"}}/>
                <div style={{position:"absolute",top:10,right:10,zIndex:4,display:"flex",flexDirection:"column",alignItems:"flex-end",gap:4}}>
                  <div style={{fontSize:10,background:"rgba(0,0,0,0.82)",padding:"3px 10px",color:"#88ff44",border:"1px solid rgba(80,200,20,0.42)",letterSpacing:2}}>
                    {planet.type.toUpperCase()}
                  </div>
                  <div style={{fontSize:9,background:"rgba(0,180,60,0.14)",padding:"2px 8px",color:"#55ee88",borderLeft:"2px solid rgba(60,200,80,0.6)",letterSpacing:1}}>
                    HAZARD LV.{planet.hazardLevel}
                  </div>
                </div>
                <div style={{position:"absolute",bottom:10,left:14,zIndex:4,fontSize:9,fontFamily:"'Orbitron',sans-serif",color:"#00e5ff",letterSpacing:3,animation:"tapFlash 1.4s ease-in-out infinite",pointerEvents:"none"}}>▶ TAP FOR FULL SCAN</div>
              </div>
              <div style={{padding:"14px 18px",display:"flex",justifyContent:"space-between",alignItems:"center",flexWrap:"wrap",gap:12,background:"rgba(0,5,12,0.98)"}}>
                <div>
                  <div style={{fontSize:8,color:"#335566",letterSpacing:3,marginBottom:4}}>SYSTEM SCAN</div>
                  <div style={{fontSize:13,color:"#44aacc",fontFamily:"'Orbitron',sans-serif",marginBottom:4,letterSpacing:1}}>{planet.system}</div>
                  <div style={{fontSize:15,color:"#00e5ff",marginBottom:2,fontFamily:"'Orbitron',sans-serif"}}>{planet.name}</div>
                  <div style={{fontSize:11,color:"#6699aa",marginTop:5}}>{planet.weather}</div>
                  <div style={{display:"flex",gap:10,marginTop:6,alignItems:"center"}}>
                    <span style={{fontSize:9,color:{"Yellow Star":"#ffcc44","Red Dwarf":"#ff5555","Blue Star":"#66aaff","Green Star":"#44ff88","Binary Star":"#ff9944","Exotic":"#cc66ff"}[planet.systemType]||"#aabbcc",letterSpacing:1}}>
                      ★ {planet.systemType||"Unknown"}
                    </span>
                    <span style={{fontSize:9,color:"#446688",letterSpacing:1}}>◎ {planet.moons||0} {(planet.moons||0)===1?"Moon":"Moons"}</span>
                  </div>
                </div>
                <div style={{textAlign:"right"}}>
                  <div style={{fontSize:22,color:"#ff6d00",fontFamily:"'Orbitron',sans-serif"}}>{cvt(planet.temperature)}{u}</div>
                  <div style={{fontSize:10,color:"#2a4a5a",marginTop:4}}>Planet {planet.planetNumber} of {planet.systemPlanetCount}</div>
                  <div style={{fontSize:9,color:"#2a4a5a",marginTop:3}}>{planet.planetClass||"Rocky"}</div>
                </div>
              </div>
            </div>
          </Panel>
        )}

        <div style={{marginTop:22,paddingTop:12,borderTop:"1px solid rgba(0,229,255,0.07)",display:"flex",justifyContent:"space-between",alignItems:"center",fontSize:9,color:"#192d38",letterSpacing:1,flexWrap:"wrap",gap:8}}>
          <div style={{display:"flex",gap:20,alignItems:"center"}}>
            <span>ATLAS WEATHER v3.0.0</span>
            <span style={{color:"#111d24"}}>--</span>
            <span>ALL ENVIRONMENTAL DATA NOMINAL</span>
          </div>
          <div style={{display:"flex",gap:14,alignItems:"center"}}>
            <span style={{color:"#2a4a5a"}}>BUILT BY ELEGRA1965</span>
            <button onClick={function(){ setSisterPopup(true); }}
              style={{background:"transparent",border:"1px solid rgba(0,229,255,0.2)",color:"#00e5ff",
                      fontSize:8,letterSpacing:2,padding:"3px 10px",cursor:"pointer",fontFamily:"'Orbitron',sans-serif"}}>
              SISTER PROJECTS
            </button>
            <span className="pulse" style={{color:"#00e5ff",whiteSpace:"nowrap"}}>SIGNAL STRONG</span>
          </div>
        </div>

        <div style={{textAlign:"center",fontSize:8,color:"#192e38",letterSpacing:1,marginTop:10,padding:"6px 0",borderTop:"1px solid rgba(0,229,255,0.04)"}}>
          A free, fan-made project inspired by the aesthetic of No Man's Sky. Not affiliated with, sponsored by, or endorsed by Hello Games.
        </div>

        {sisterPopup && (
          <div className="modal-bg" onClick={function(){ setSisterPopup(false); }}>
            <div className="modal scan-in" onClick={function(e){ e.stopPropagation(); }} style={{maxWidth:380,padding:24}}>
              <span className="corner-tr" style={{position:"absolute",top:-1,right:-1}}/>
              <span className="corner-bl" style={{position:"absolute",bottom:-1,left:-1}}/>
              <div style={{fontFamily:"'Orbitron',sans-serif",fontSize:13,color:"#00e5ff",marginBottom:18,letterSpacing:2}}>SISTER PROJECTS</div>
              <a href="https://nms-theme-pack.netlify.app" target="_blank" rel="noreferrer" style={{display:"block",padding:"12px 16px",marginBottom:10,background:"rgba(0,229,255,0.04)",border:"1px solid rgba(0,229,255,0.2)",color:"#00e5ff",textDecoration:"none",fontSize:12,letterSpacing:1}}>⟁ NMS THEME PACK</a>
              <a href="https://nms-atlas-interface-ai.netlify.app" target="_blank" rel="noreferrer" style={{display:"block",padding:"12px 16px",background:"rgba(0,229,255,0.04)",border:"1px solid rgba(0,229,255,0.2)",color:"#00e5ff",textDecoration:"none",fontSize:12,letterSpacing:1}}>⟁ ATLAS INTERFACE AI</a>
              <button className="btn-r" onClick={function(){ setSisterPopup(false); }} style={{marginTop:20,padding:"6px 20px",fontSize:11,letterSpacing:2}}>CLOSE</button>
            </div>
          </div>
        )}
        {modal && <Modal onClose={function(){ setModal(false); }} cvt={cvt} u={u} planet={planet}/>}
      </div>
    </div>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(React.createElement(App));
